import { z } from "zod";

import { isRequired, snakeToCamel, type TableSchemas } from "./databaseDoc";
import type { DatabaseColumnRow, ForeignKeyRow, IndexRow } from "./rows";
import type { DatabaseDocInput } from "./typeSchemas";

/** A column of a Markdown table: its header and how to read its cell from one row. */
type GridColumn<Row> = [header: string, cell: (row: Row) => string];

const HEADER = [
  "# Database",
  "",
  "> Generated by `pnpm db:docs` from the migrations and `src/worker/db/tableSchemas.ts`. Do not edit it by hand.",
  ">",
  "> Descriptions come from the table schemas; columns, types, keys and indexes come from the migrated database.",
  ">",
  "> Required counts a primary key as required, as the app does; SQLite lets a non-INTEGER primary key hold NULL.",
].join("\n");

/**
 * The Markdown reference for the database. The text is deterministic and already formatted as
 * `oxfmt` wants it, so a stale committed copy shows up as a plain string difference.
 */
export function renderDatabaseDoc(input: DatabaseDocInput, tableSchemas: TableSchemas): string {
  const tableNames = [...new Set(input.columns.map((column) => column.tableName))].toSorted(
    compareText,
  );
  const sections = [
    HEADER,
    renderDiagram(input, tableSchemas, tableNames),
    ...tableNames.map((tableName) => renderTable(input, tableSchemas, tableName)),
  ];

  return `${sections.join("\n\n")}\n`;
}

function renderDiagram(
  input: DatabaseDocInput,
  tableSchemas: TableSchemas,
  tableNames: string[],
): string {
  const entities = tableNames.flatMap((tableName) => {
    const attributes = columnsOf(input, tableName).map((column) =>
      renderAttribute(input, tableSchemas, column),
    );

    return [`  ${tableName} {`, ...attributes, "  }"];
  });
  const relationships = input.foreignKeys
    .toSorted(
      (a, b) => compareText(a.tableName, b.tableName) || compareText(a.fromColumn, b.fromColumn),
    )
    .map((foreignKey) => renderRelationship(input.columns, foreignKey));

  return ["```mermaid", "erDiagram", ...entities, ...relationships, "```"].join("\n");
}

function renderAttribute(
  input: DatabaseDocInput,
  tableSchemas: TableSchemas,
  column: DatabaseColumnRow,
): string {
  const keys = [
    column.primaryKey > 0 ? "PK" : undefined,
    input.foreignKeys.some(
      (foreignKey) =>
        foreignKey.tableName === column.tableName && foreignKey.fromColumn === column.name,
    )
      ? "FK"
      : undefined,
    isUnique(input.indexes, column) ? "UK" : undefined,
  ].filter((key) => key !== undefined);
  const description = columnDescription(tableSchemas, column);
  const parts = [
    column.type,
    column.name,
    keys.join(", "),
    description === "" ? "" : `"${description.replaceAll('"', "'")}"`,
  ].filter((part) => part !== "");

  return `    ${parts.join(" ")}`;
}

/** A column alone in a unique index or constraint. The primary key already has its own marker. */
function isUnique(indexes: IndexRow[], column: DatabaseColumnRow): boolean {
  return indexes.some(
    (index) =>
      index.tableName === column.tableName &&
      index.unique === 1 &&
      index.partial === 0 &&
      index.origin !== "pk" &&
      index.columns.length === 1 &&
      index.columns[0] === column.name,
  );
}

function renderRelationship(columns: DatabaseColumnRow[], foreignKey: ForeignKeyRow): string {
  const column = columns.find(
    (candidate) =>
      candidate.tableName === foreignKey.tableName && candidate.name === foreignKey.fromColumn,
  );
  if (column === undefined) {
    throw new Error(
      `foreign key column ${foreignKey.tableName}.${foreignKey.fromColumn} is unknown`,
    );
  }
  const link = isRequired(column) ? "}o--||" : "}o--o|";

  return `  ${foreignKey.tableName} ${link} ${foreignKey.parentTable} : "${foreignKey.fromColumn}"`;
}

function renderTable(
  input: DatabaseDocInput,
  tableSchemas: TableSchemas,
  tableName: string,
): string {
  const description = printable(
    descriptionOf(tableSchemas[tableName]),
    `the description of table ${tableName}`,
  );
  const indexes = input.indexes
    .filter((index) => index.tableName === tableName)
    .toSorted((a, b) => compareText(a.name, b.name));
  const tableSql = input.tableSql.find((row) => row.tableName === tableName);
  if (tableSql === undefined) {
    throw new Error(`table ${tableName} has no CREATE TABLE statement`);
  }

  const columnGrid = renderGrid<DatabaseColumnRow>(
    [
      ["Column", (column) => cell(`\`${column.name}\``, `${tableName}.${column.name}`)],
      ["Type", (column) => cell(column.type, `${tableName}.${column.name} type`)],
      ["Required", (column) => (isRequired(column) ? "yes" : "no")],
      [
        "Default",
        (column) =>
          column.defaultValue === null
            ? ""
            : cell(`\`${column.defaultValue}\``, `${tableName}.${column.name} default`),
      ],
      [
        "Description",
        (column) =>
          cell(columnDescription(tableSchemas, column), `${tableName}.${column.name} description`),
      ],
    ],
    columnsOf(input, tableName),
  );
  const indexGrid = renderGrid<IndexRow>(
    [
      ["Name", (index) => cell(`\`${index.name}\``, `index ${index.name}`)],
      ["Kind", indexKind],
      ["Columns", (index) => cell(index.columns.join(", "), `index ${index.name} columns`)],
      ["Condition", (index) => cell(indexCondition(index), `index ${index.name} condition`)],
    ],
    indexes,
  );

  return [
    `## ${tableName}`,
    ...(description === "" ? [] : [description]),
    "### Columns",
    columnGrid,
    ...(indexes.length === 0 ? [] : ["### Indexes", indexGrid]),
    renderCreateStatement(tableSql.sql),
  ].join("\n\n");
}

function indexKind(index: IndexRow): string {
  if (index.origin === "pk") {
    return "primary key";
  }
  if (index.origin === "u") {
    return "unique constraint";
  }

  return index.unique === 1 ? "unique index" : "index";
}

/** The text after WHERE of a partial index, in code style; empty for any other index. */
function indexCondition(index: IndexRow): string {
  const condition = /\sWHERE\s([\s\S]+)/i.exec(index.sql ?? "")?.[1];

  return condition === undefined ? "" : `\`${collapse(condition)}\``;
}

function renderCreateStatement(sql: string): string {
  const lines = sql.split("\n").map((line) => line.trimEnd());

  return [
    "<details>",
    "<summary>CREATE TABLE statement</summary>",
    "",
    "```sql",
    ...lines,
    "```",
    "",
    "</details>",
  ].join("\n");
}

/** A Markdown table with every column padded to its widest cell, as `oxfmt` lays it out. */
function renderGrid<Row>(columns: GridColumn<Row>[], rows: Row[]): string {
  const sized = columns.map(([header, readCell]) => ({
    header,
    readCell,
    width: Math.max(header.length, ...rows.map((row) => readCell(row).length)),
  }));
  const line = (text: (column: (typeof sized)[number]) => string) =>
    `| ${sized.map((column) => text(column).padEnd(column.width)).join(" | ")} |`;

  return [
    line((column) => column.header),
    line((column) => "-".repeat(column.width)),
    ...rows.map((row) => line((column) => column.readCell(row))),
  ].join("\n");
}

function columnsOf(input: DatabaseDocInput, tableName: string): DatabaseColumnRow[] {
  return input.columns
    .filter((column) => column.tableName === tableName)
    .toSorted((a, b) => a.cid - b.cid);
}

function columnDescription(tableSchemas: TableSchemas, column: DatabaseColumnRow): string {
  return printable(
    descriptionOf(tableSchemas[column.tableName]?.shape[snakeToCamel(column.name)]),
    `the description of ${column.tableName}.${column.name}`,
  );
}

/** The `.meta({ description })` of a schema as one line; empty when it has none. */
export function descriptionOf(schema: z.core.$ZodType | undefined): string {
  if (schema === undefined) {
    return "";
  }

  return collapse(z.globalRegistry.get(schema)?.description ?? "");
}

/** Text safe inside a table cell: one line, with pipes escaped. */
function cell(text: string, where: string): string {
  return collapse(printable(text, where)).replaceAll("|", "\\|");
}

/** oxfmt pads a table by display width, so a wide character would break the round trip. */
function printable(text: string, where: string): string {
  const character = /[^\x20-\x7e\n\r\t]/.exec(text)?.[0];
  if (character !== undefined) {
    throw new Error(
      `${where} has ${JSON.stringify(character)}, which is not printable ASCII: ${JSON.stringify(text)}`,
    );
  }

  return text;
}

function collapse(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function compareText(a: string, b: string): number {
  if (a === b) {
    return 0;
  }

  return a < b ? -1 : 1;
}
